namespace Server;

/// <summary>发送方按连接号发。</summary>
public sealed class GoodPublisher(IHubContext<NotificationHub, INotificationReceiver> hub)
{
    public Task SendAsync(IReadOnlyList<string> ids) => hub.Clients.Clients(ids).ReceivePresenceSummary(new());
}

namespace Server;

public sealed class BadService
{
    private readonly IHubContext<NotificationHub> _hub;
    public Task Send(string id) => _hub.Clients.Client(id).SendAsync("x");
    public Task Shout() => _hub.Clients.All.SendAsync("x");
}

namespace Server;

public sealed class BadHub : Hub
{
    public Task Shout() => Clients.All.SendAsync("x");
    public Task Others() => Clients.AllExcept([Context.ConnectionId]).SendAsync("x");
    public Task Me() => Clients.Caller.SendAsync("x");
}

namespace Server;

// 推送按连接，禁止 Clients.All，也不要直接拿 IHubContext。
public sealed class CommentOnly
{
    public string Hint => "不要写 Clients.All";
}

namespace Relay;

public sealed class RelayServer
{
    public required ClientRegistry Clients { get; init; }
    public bool Check(string token) => Clients.Authenticate(token) is not null;
}

namespace Server;

public sealed class StrayHub : Hub<INotificationReceiver>
{
    public Task Me() => Clients.Caller.Ping();
}

